use vstd::prelude::*;

verus! {
    // Specification for the solve function
    fn solve(n: u8, k: u8, participations: Vec<u8>) -> (teams: u8)
        requires
            n <= participations.len() as u8, // Ensure n does not exceed the length of participations
            k <= 5, // Ensure k is within the valid range
        ensures
            teams == (participations.iter().take(n as usize).filter(|&&attendance| {
                5 - attendance >= k
            }).count() / 3) as u8, // Ensure the result matches the expected number of teams
    {
        // Determine the number of participants to consider
        let count = participations.iter().take(n as usize).filter(|&&attendance| {
            // Check if the participant is eligible
            5 - attendance >= k
        }).count();
        
        // Calculate the number of teams of 3 that can be formed
        (count / 3) as u8
    }

    fn main() {
        // Example usage
        let n = 5;
        let k = 2;
        let participations = vec![1, 2, 3, 4, 5, 0];
        let result = solve(n, k, participations);
        println!("Maximum number of teams: {}", result);
    }
}